quests[8705] = { id = 8705, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gavel of Infinite Wisdom", description = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, {name}, and I will make you a powerful weapon from the finest Qiraji materials.", progress = "Did you bring me the components I require, {name}?", completion = "You've done well, {class}.  This is a masterwork hilt... the balance is perfect.\n\nTake your weapon, {name}.  Wield it with great confidence and vanquish our enemies!", objectives = "Bring 1 Qiraji Ornate Hilt, 2  Lambent Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
