quests[8727] = { id = 8727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farwhisper the Elder", sourceObjective = "The heavens, in their countless stars, hold answers to earthly mysteries, {name}.  Might, then, the wise, and the lucky, gaze up and find truth?", sourceObjectiveStatus = "unverified-source-field" }
quests[8728] = { id = 8728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good News and The Bad News", description = "Well that took a little longer than expected. Now let me see what this ledger says.\n\n<Narain silently reads the ledger, periodically mumbling under his breath.>\n\n The good news is that I am 99% certain that I am capable of creating an arcanite buoy that will function to your specifications. This is, of course, wholly dependant on the bad news.\n\nThe bad news is that I'm going to need a lot of arcanite, elementium ore, and rare gemstones.\n\nBring me what I need and I will craft the buoy.", progress = "Arcanite buoys don't just make themselves, {name}. And NO, you cannot borrow some money.", completion = "A deal is a deal. I sure hope you know what you are getting yourself into, {name}. This is an awful lot of trouble to go through to do some fishing.", objectives = "Narain Soothfancy in Tanaris wants you to bring him 20 Arcanite Bars, 10 Elementium Ore, 10 Azerothian Diamonds, and 10 Blue Sapphires.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8729] = { id = 8729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrath of Neptulon", description = "Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit.\n\nAccording to my superior psycho-psionic clairvoyance, you'll find that the best spot to cast this buoy is off the coast of Azshara, in the Bay of Storms.\n\nLook for a swirling maelstrom, most likely cluttered with wreckage.\n\nBy the by, I hope you have friends.\n\nNow if you somehow miraculously succeed, take the scepter shard to Anachronos.", progress = "Time is running out, champion.", completion = "Well done, {name}. I will be able to reform the Scepter of the Shifting Sands soon.", objectives = "Use the Arcanite Buoy at the Swirling Maelstrom at the Bay of Storms in Azshara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8730] = { id = 8730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nefarius's Corruption", description = "Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it... But what would tragedy be without cruelty?\n\n<Vaelastrasz coughs weakly.>\n\nNe... Nefarius now holds the scepter shard.\n\nTime is of the essence. Nefarius plans to destroy the shard. You must hurry!", progress = "Another of our heroes lost to the spawn of Deathwing. We will be cursed with this suffering forever...", completion = "Vaelastrasz's soul is at ease, champion. The Aspects all watch your progress with great interest. Know that you have powerful allies.\n\nI was commanded to grant you something to aid you in this struggle. Use it well...", objectives = "Slay Nefarian and recover the Red Scepter Shard. Return the Red Scepter Shard to Anachronos at the Caverns of Time in Tanaris. You have 5 hours to complete this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8731] = { id = 8731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Duty", description = "Greetings, {name}.  Before I assign you to more involved tasks in the war, you'll need to do your share of field duty.  \n\nYou will find Captain Skullsplit's Orgrimmar Legion outside Hive'Regal.\n\nReport to him and come back to me with proof of your field service.  I shall have a more advanced assignment ready for you.\n\nOh, please do your best to stay away from the Ironforge Brigade.  Tensions are high among our Alliance and Horde volunteers.", progress = "You've completed your field duty, {name}?  Captain Skullsplit can be found outside of Hive'Regal.", completion = "I can tell that Krug has little use for paperwork.  He signed this in silithid blood!\n\nVery well, {name}.  I've prepared a set of tasks that should make good use of your skills as a {class}.\n\nWith the continued efforts of you and people like you, our enemy will soon be crushed!", objectives = "Report to Krug Skullsplit at the Orgrimmar Legion post in front of Hive'Regal. Prepare your Unsigned Field Duty Papers, obtain Signed Field Duty Papers and bring them to Windcaller Kaldon in Cenarion Hold.\n\nNote: Healing or casting beneficial spells on a member of the Orgrimmar Legion will flag you for PvP.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8732] = { id = 8732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Duty Papers", progress = "Field duty papers?  What manner of nonsense is this, {name}?", completion = "In the old days I would've marked your forehead with the creature's blood to mark your accomplishment here.  Thrall insists we comply with the Druids' requests.\n\nHere, take these papers and go back to Cenarion Hold.  I'm sure they will have suitable work for you." }
quests[8733] = { id = 8733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eranikus, Tyrant of the Dream", description = "This is a journey of redemption, hero. Would it be that I was slain today, I would have died for a just and righteous cause. You must recover the green scepter shard. You must cleanse Eranikus of the taint placed upon him by the Old Gods.\n\nTravel to Darnassus. Just outside the city walls you will find one of my agents. This agent will set things in motion for us and inform Tyrande of our plans without alerting Staghelm.\n\n<Malfurion sighs.>\n\nA fall from grace a thousand years in the making...", completion = "The wisp is silent except for a low humming sound. Oddly enough, it is able to communicate with you through thoughts.", objectives = "Travel to the continent of Teldrassil and find Malfurion's agent somewhere outside the walls of Darnassus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8734] = { id = 8734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrande and Remulos", description = "Tyrande will be notifed, mortal. Shan'do Stormrage has prepared me for this contingency.\n\nNow you must venture to the Moonglade and speak with Remulos. He will have further instruction as to the summoning of Eranikus.\n\nWe all wish you great luck.", completion = "It would be impossible to pull Eranikus from the Dream should he refuse. His intentions, however, require him to enter our world. He seeks to destroy the living manifestation of Malfurion. To do this successfully would mean an end to one of the most powerful allies of the Dream. The Nightmare would wholly consume all that would remain should Malfurion fall...", objectives = "Travel to the Moonglade and speak to Keeper Remulos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8735] = { id = 8735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightmare's Corruption", description = "You must travel to the four dream portals of Azeroth. From each you must draw a fragment of the Nightmare's corruption. The dragonkin that inhabit these areas will hold such fragments. Return to me when you have gathered these fragments.", progress = "<Remulos is lost deep in thought.>", completion = "Are you prepared? Is the world prepared for what we are about to invoke? I do not know... I am bound by duty to Malfurion. Duty and honor...", objectives = "Travel to the four Emerald Dream portals in Azeroth and collect a Fragment of the Nightmare's Corruption from each. Return to Keeper Remulos in the Moonglade when you have completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8736] = { id = 8736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightmare Manifests", description = "We must use restraint against Eranikus. We are to redeem him not destroy him.\n\nTyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction.\n\nBe on guard! You and your allies are our only hope.", completion = "He is redeemed, {name}. He now returns to the Dream to right what he alone has done wrong. Eranikus will be a powerful ally to Malfurion and my father.\n\nThese armaments are for you, {name}; given to me by Ysera herself. You would do well to make use of them in your battles against the Qiraji.", objectives = "Defend Nighthaven from Eranikus. Do not let Keeper Remulos perish. Do not slay Eranikus. Defend yourself. Await Tyrande.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8737] = { id = 8737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azure Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy an Azure Templar and report to Bor Wildmane.", progress = "Is your task done yet, {name}?", completion = "Good job, {name}.  Here's your next assignment.", objectives = "Summon and slay an Azure Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing I in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8738] = { id = 8738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hive'Regal Scout Report", description = "We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Landion has been watching the silithid movements at Hive'Regal for several days now.  Find him and obtain a written report.  We need to be able to act on that information as soon as possible, {name}.", progress = "You'll find Scout Landion inside Hive'Regal.  Hurry, {name}!  Time is of the essence.", completion = "Your efforts are greatly appreciated, {name}.  I'll read these scouting reports right away, feel free to go over your next assignment.", objectives = "Contact Cenarion Scout Landion inside Hive'Regal and return the Hive'Regal Scout Report to Windcaller Proudhorn at Cenarion Hold. You must also bring Tactical Task Briefing VII in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8739] = { id = 8739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hive'Ashi Scout Report", description = "We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Jalia has been watching the silithid movements at Hive'Ashi for several days now.  Find her and obtain a written report.  We need to be able to act on that information as soon as possible, {name}.", progress = "You'll find Scout Jalia inside Hive'Ashi.  Hurry, {name}!  Time is of the essence.", completion = "Your efforts are greatly appreciated, {name}.  I'll read these scouting reports right away, feel free to go over your next assignment.", objectives = "Contact Cenarion Scout Jalia inside Hive'Ashi and return the Hive'Ashi Scout Report to Windcaller Proudhorn at Cenarion Hold. You must also bring Tactical Task Briefing VIII in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8740] = { id = 8740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Marauders", description = "Bands of mounted Twilight's Hammer cultists have been spotted riding outside the reach of our forces in Cenarion Hold, picking off our smaller patrols and caravans.\n\nFind and defeat the twilight marauders along with their leader, a terrible warrior by the name of Morna.  Report to Windcaller Proudhorn after completing the task.", progress = "Is your task done yet, {name}?", completion = "Well done, {name}.  The twilight marauders were inflicting an unacceptable number of casualties on our patrols.  Here's your next assignment.", objectives = "Slay Twilight Marauder Morna and 5 Twilight Marauders. Report to Windcaller Proudhorn when your task is finished. You must also bring Tactical Task Briefing IX in order to complete this quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8741] = { id = 8741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion Returns", description = "The keeper awaits your return, {name}. Take the green scepter shard to Anachronos at the Caverns of Time.", progress = "<Anachronos nods.>", completion = "Your deeds will be known to all, champion. They will sing your praises from Orgrimmar to the far reaches of the South Seas. All will know of the champion of the Bronze Flight, {name}.", objectives = "Take the Green Scepter Shard to Anachronos at the Caverns of Time in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8742] = { id = 8742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of Kalimdor", sourceObjective = "A thousand years has passed and just as it was fated, one stands before me. One who shall lead their people to a new age.\n\nThe Old God trembles, {name}. Oh yes, it fears your faith. Shatter the prophecy of C'Thun.\n\nIt knows you come, champion - and with you comes the might of Kalimdor. You have only to let me know when you are prepared and I shall grant you the Scepter of the Shifting Sands.", sourceObjectiveStatus = "unverified-source-field" }
quests[8743] = { id = 8743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bang a Gong!", progress = "The Scarab Gong looms ominously before you. Steel yourself, {name}; for once The Scarab Gong is rung, the gates of Ahn'Qiraj will be opened.\n\nFrom the slackened maw of the beast can only come chaos and destruction. Defend your people!", completion = "From the ground near the gong springs a special crystal. Perhaps favor from the Brood." }
quests[8744] = { id = 8744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Carefully Wrapped Present", sourceObjective = "The tag on this present reads:\n\nTo {name},\n\nMay your feast of Great-Winter be merry and bright!", sourceObjectiveStatus = "unverified-source-field" }
quests[8745] = { id = 8745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure of the Timeless One", sourceObjective = "Greetings, champion. I am Jonathan, keeper of the sacred gong and eternal watcher of the Bronze Flight.\n\nI have been empowered by the Timeless One himself to grant you an item of your choosing from his timeless treasure trove. May it aid you in your battles against C'Thun.", sourceObjectiveStatus = "unverified-source-field" }
quests[8746] = { id = 8746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Great-father Winter's eight reindeer - and property of Smokywood Pastures.  We've received not one but TWO ransom letters from groups claiming to have Metzen.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen and return him to us!\n\nCheck out the ransom letters for clues, and sprinkle this reindeer dust on him - it will free him from any of his bonds!\n\nPlease, hurry!", progress = "{name}!  Did you find him?  Were the notes in the satchel I gave you enough information to locate Metzen?  I hate to think of that those cruel thugs might do to him... but there's no way we can afford to pay such an exorbitant ransom!", completion = "You did it!  Huzzah!\n\nMetzen flew back into Great-father Winter's stables - yes Metzen can really fly - just a little while ago!  The dust worked like a charm; I knew it would.  You've saved the Feast of Winter Veil as well as Smokywood Pastures from disaster.  Thank you, {name}.\n\nListen... because of what you've done here, I want you to have this.  It's something VERY special; if you have a mount, I think you'll get a kick out of it.  Happy Winter Veil!", objectives = "Find Metzen the Reindeer. Use the notes provided to you for clues as to where he is being held.\n\nWhen you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\n\nReturn the Pouch of Reindeer Dust to Kaymard Copperpinch in Orgrimmar once Metzen is freed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8747] = { id = 8747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Protector", sourceObjective = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the defender will offer superior protection against the forces of evil.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[8748] = { id = 8748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Protector", progress = "Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the protector!" }
quests[8749] = { id = 8749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Protector", progress = "You honor my kind, {name}. Strike down the enemies of Kalimdor! Show them what it means to deface the land of eternal starlight.\n\nYou have earned another enhancement. Hand me your signet ring so that I may bolster its power.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the protector!" }
quests[8750] = { id = 8750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Protector", progress = "Dedication of this magnitude is a rarity. You have shown that your will is unfaltering, {name}. You shall be greatly rewarded for your stalwart watch over our world.\n\nHand me your signet ring so that I may strengthen its enchantment.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the protector!" }
quests[8751] = { id = 8751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Protector of Kalimdor", progress = "Never have I seen such tenacity! The Bronze Flight grants you one final enchantment. The Timeless One himself has requested it so!\n\nHand me your signet ring so that I may make the necessary adjustments.", completion = "Rise, Protector of Kalimdor! Rise and be recognized!" }
quests[8752] = { id = 8752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Conqueror", sourceObjective = "Impressive, little one. You have gone through much trouble to gain the favor of the Bronze Flight. Your dedication is noted.\n\nThe signet ring of the conqueror will greatly enhance your physical attacks.\n\nBe warned, once you have chosen your path, you will have no recourse should you change your mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[8753] = { id = 8753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of the Conqueror", progress = "Your continued defense of the children of Kalimdor has been acknowledged. Hand me your signet ring so that I may enhance its powers.", completion = "Your rise amongst the rank of the Brood is most impressive, {name}. May you never stray from the path of the conqueror!" }
