quests[8843] = { id = 8843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", progress = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I'll make sure that you receive a significant acknowledgement of your deeds with Thunder Bluff.  I also accept single tokens, but at a much reduced rate of recognition.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly take your signets if you are ready to hand in a set.", completion = "Excellent!  It is no small sacrifice that you've made to earn these signets, and you will be acknowledged for your service appropriately.  It's adventurers like you, {name}, that truly make a difference.\n\nLet me know if you have additional signets to hand in; I'll gladly help you out with whatever ones you need exchanged." }
quests[8844] = { id = 8844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Commendation Signet", progress = "For those adventurers who have but a single commendation signet, I'll exchange it for a small amount of recognition with the Darkspear tribe.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  We offer a single signet exchange as a service for those who don't have enough for a full stack of ten.\n\nWith that being said, I stand ready to assist you if you still wish to hand in a single signet.", completion = "Very well - your deeds have been entered into the records, and you are duly recognized for your efforts.  Keep up the good work, {class}.\n\nIf you have any more signets to hand in, then I am able to assist you further in that regard." }
quests[8845] = { id = 8845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Commendation Signets", progress = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I'll make sure that you receive a significant acknowledgement of your deeds with the Darkspear tribe.  I also accept single tokens, but at a much reduced rate of recognition.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly take your signets if you are ready to hand in a set.", completion = "Excellent!  It is no small sacrifice that you've made to earn these signets, and you will be acknowledged for your service appropriately.  It's adventurers like you, {name}, that truly make a difference.\n\nLet me know if you have additional signets to hand in; I'll gladly help you out with whatever ones you need exchanged." }
quests[8846] = { id = 8846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Five Signets for War Supplies", progress = "Ah, here for additional supplies for yourself, are you?  Well, I can certainly understand the need for additional materiel... just take a look around if you need any proof.\n\nI'll issue you some additional supplies, but you'll need to give me an appropriate number of commendation signets in exchange.  You won't receive any recognition for surrendering the signets in this manner, but you might find something useful that will help keep you alive when battle is finally upon us.", completion = "Well then, it's settled; here are your supplies, {class}.  If you wish to do an additional exchange, then I am prepared to authorize it.  Just give me the word and I'll make it happen.\n\nKeep up the good work, {name}.  We need all the materiel we can muster if we're going to win this thing.  If we all do our part, then victory shall be ours for the taking!" }
quests[8847] = { id = 8847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ten Signets for War Supplies", progress = "Ah, here for additional supplies for yourself, are you?  Well, I can certainly understand the need for additional materiel... just take a look around if you need any proof.\n\nI'll issue you some additional supplies, but you'll need to give me an appropriate number of commendation signets in exchange.  You won't receive any recognition for surrendering the signets in this manner, but you might find something useful that will help keep you alive when battle is finally upon us.", completion = "Well then, it's settled; here are your supplies, {class}.  If you wish to do an additional exchange, then I am prepared to authorize it.  Just give me the word and I'll make it happen.\n\nKeep up the good work, {name}.  We need all the materiel we can muster if we're going to win this thing.  If we all do our part, then victory shall be ours for the taking!" }
