quests[8856] = { id = 8856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desert Survival Kits", description = "With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.", objectives = "Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Baked Salmon to Calandrath at the inn in Cenarion Hold in Silithus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8857] = { id = 8857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Colossus - Ashi", description = "I'm looking for battle hardened adventurers willing and able to get a fresh husk sample from the fallen Colossus of Ashi to Oglethorpe in Booty Bay. No, no, I wouldn't want you to go anywhere near that thing's corpse. Just take one of my samples and make it snappy. These things are no good to him rotten!", progress = "Yes? What have you got there?", completion = "Oh the chickens I will craft from this wondrous husk! Well done, my boy!", objectives = "Take the Colossus of Ashi's Husk to Oglethorpe Obnoticus in Booty Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8858] = { id = 8858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Colossus - Regal", description = "There ain't nothin' I'd like more than to stuff this bug husk down Oilfist's fat face... Cept, I'm stuck here collectin' samples from that overgrown cockroach. I'll be here 'till the wee mornin' hours given the size o' that thing.\n\nTake this here sample to Oilfist fer me and do it fast, {class}. He's payin' BIG!\n\nYar, Thorium Point - it be in the Searin' Gorge.", progress = "Hmmm...", completion = "Excellent. We could surely devise some incredibly powerful armor from this chitin. Here's the riches you were promised.", objectives = "Take the Colossus of Regal's Husk to Overseer Oilfist in Searing Gorge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8859] = { id = 8859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Colossus - Zora", description = "My servants were nearly killed in their efforts to recover this sample. You absolutely must hurry! Lord Maxwell Tyrosus eagerly awaits a fresh husk sample. He believes that the secrets of this Colossus could help us in the war against the Scourge!\n\nWhy are you still here!? To Light's Hope! Yes, you will be rewarded handsomely for your efforts...", progress = "You look a bit heavy in the boots, friend.", completion = "Excellent and timely! Well done, lad.", objectives = "Take the Colossus of Zora's Husk to Lord Maxwell Tyrosus at Light's Hope Chapel in the Eastern Plaguelands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8860] = { id = 8860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Year Celebrations!", description = "Stormwind is holding a celebration for the new year!  All day long today you can get free booze, and at night they'll put on a firework show!  It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!\n\nWell anyway, Innkeeper Allison in Stormwind needs a supply of Smoky Wood Pasture fare to help feed all the party goers.  Can you do me a favor and deliver it!\n\nThanks, {name}!  Innkeeper Allison is in the Gilded Rose, in the Trade District of Stormwind.", progress = "Greetings!  Are you here for the party!  Or perhaps you just need to rest those weary feet of yours...", completion = "Oh, my Smokywood supplies!  Splendid!  I'll need these to feed all the people in town for the celebration!\n\nThank you, {name}.  Please take this as payment, and don't forget to drink and dance with the revelers outside!", objectives = "Bring the Smokywood Supplies to Innkeeper Allison in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8861] = { id = 8861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Year Celebrations!", description = "Thunder Bluff is holding a celebration for the new year!  All day you'll find free booze there, and at night they'll put on a firework show!\n\nIt should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!\n\nWell anyway, Innkeeper Pala in Thunder Bluff needs a supply of Smoky Wood Pasture fare to help feed all the party goers.  Can you do me a favor and deliver it!\n\nThanks, {name}!  Innkeeper Pala is in the inn near the bridge to Hunter's Rise.", progress = "Good day, {class}!  Did you come to Thunder Bluff for our celebrations?  Or are you here to rest a weary hoof between hunts?", completion = "Oh, very good!  These supplies will help feed all our people, here to celebrate the new year!\n\nI thank you, {name}.  You are in my debt.  Please, take these coins... and heed my advice - drink heartily from the kegs outside, and join our revelers in a dance of celebration!", objectives = "Bring the Smokywood Supplies to Innkeeper Pala in Thunder Bluff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8862] = { id = 8862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Candle", progress = "Elune's candle is an artifact of great reverence to the disciples of the Lunar Festival.  Stored within the candle is true moonlight, ready to be unleashed!\n\nThis light is harmless to most creatures, but you will find that Omen and his minions are burned and dazzled by it.", completion = "Very well then - I accept these coins of ancestry.  Please take Elune's candle with my blessing.  Also, please enjoy these complimentary fireworks.\n\nMay your Lunar Festival be joyous and filled with merriment, {name}.\n\nAnd if you choose to face Omen and his minions, you will find Elune's candle quite useful..." }
quests[8863] = { id = 8863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festival Dumplings", progress = "If you are hungry, then you have come to the right place my friend!\n\nDumplings are the traditional food of the Lunar Festival; it has been served since the time of the first Lunar Festival, and I am pleased to be able to offer it at this one.  In exchange for just a single coin of ancestry, I will share with you a sampling of one of the tastiest dishes you will ever enjoy!", completion = "Excellent - please enjoy these dumplings with my compliments.  While they are but a small token of appreciation for the honor you have brought upon yourself through your actions, I think you will enjoy them all the same.\n\nShould you have any more coins of ancestry, I stand ready to offer you a wide array of items in exchange." }
quests[8864] = { id = 8864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festive Lunar Dresses", progress = "I have a selection of dresses that may be of interest to you.  Such dresses have been worn in times past during the Lunar Festival, and the selection I have today is perhaps the finest I have ever seen.  Each is hand-crafted with only the finest and softest of components.\n\nIn exchange for some coins of ancestry, I will let you choose one of the three styles I have to keep as your own.  Is this acceptable to you?", completion = "Very well then - I accept these coins of ancestry.  Please take your dress with my blessing.  Also, please enjoy these complimentary fireworks.\n\nAs you have honored your elders, you honor me with your mere presence.  Thank you, and may your Lunar Festival be joyous." }
quests[8865] = { id = 8865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festive Lunar Pant Suits", progress = "I am please to inform you that I have a fine selection of festive pant suits available for you to own... but only in trade for coins of ancestry.  If fashion is important to you, then these are what you're looking for!  I assure you that you will not find pant suits like these anywhere else.\n\nIn exchange for some coins of ancestry, I will let you choose one of the three styles I have to keep as your own.  Is this acceptable to you?", completion = "Very well then - I accept these coins of ancestry.  Please take your pant suit with my blessing.  Also, please enjoy these complimentary fireworks.\n\nShould you have more coins of ancestry to trade, then speak with me again.  I will be offering various items throughout the entirety of the Lunar Festival." }
quests[8866] = { id = 8866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bronzebeard the Elder", sourceObjective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, {name}, and offer you this token...", sourceObjectiveStatus = "unverified-source-field" }
quests[8867] = { id = 8867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunar Fireworks", description = "Every year the druids of Moonglade hold a celebration of our city's great triumph over an ancient evil.\n\nWe celebrate the wisdom of our elders, share in magnificent feasts and of course... shoot fireworks!\n\nFor a small donation you can purchase colorful rockets from our vendor.  Try using some of the launchers around here, {name}.", progress = "Did you find the launchers, {name}?", completion = "Well done, {name}.\n\nNow that you're in the spirit of things, why don't you take this invitation to the festival in Moonglade.\n\nIt's quite an enjoyable celebration, if you have the time to spare.  We share food, drink, stories and of course... more fireworks!\n\nOpen the invitation while standing inside the circle of greater moonlight and you'll be transported to Moonglade.", objectives = "Launch 8 Lunar Fireworks and 2 Cluster Fireworks and return to a Lunar Festival Harbinger at any capital city.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8868] = { id = 8868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Blessing", description = "The beast Omen was once a hero of this world.  A wolf of great strength and fortune, Omen fought beside the heroes of the War of the Ancients until he succumbed to demonic magics.  Turning against his allies, he raged across Azeroth and carried death and terror in his wake.\n\nFinally defeated here, in Moonglade, Omen now sleeps among the silt of Lake Elune'ara.  But each new year, during the festival, he stirs...\n\nGather cohorts, {name}, and summon and defeat the beast Omen.  Earn the blessing of Elune!", progress = "Omen yet stirs below below Lake Elune'ara, {name}...", completion = "Very well done, {name}.  Defeating Omen sent his spirit back to the waters of Elune'ara.  Although the beast himself is blessed by Elune and so cannot die, his anger will subside for another year.\n\nYour victory is a celebration, {name}--a celebration of the might of Omen, of you and your allies, and of the peace you have given this tragic hero of our past.", objectives = "Summon Omen, defeat him and gain Elune's Blessing. Return to Valadar Starsong in Nighthaven", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8869] = { id = 8869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet Serenity", description = "Within the confines of the Scarlet Bastion lies sweet Serenity. The Crimson Hammersmith guards the recipe with his life. Defeat him and bring me his apron. For that, I shall train you to become a hammersmith.\n\nUnderstand this: Once you have chosen the path of the hammersmith, the paths of the swordsmith and axesmith will no longer be available.", objectives = "Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8870] = { id = 8870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", completion = "Welcome, {name}.  You're here to join us in our celebration?", objectives = "Talk to the Lunar Festival Harbinger in the Mystic Ward of Ironforge. You can also talk to Lunar Festival Harbingers in other capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8871] = { id = 8871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", completion = "Welcome, {name}.  Are you here to join in the festivities?", objectives = "Talk to the Lunar Festival Harbinger in the Park District in Stormwind. You can also talk to Lunar Festival Harbingers in other capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8872] = { id = 8872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", completion = "Welcome, {name}.  Are you here to join in the festivities?", objectives = "Talk to the Lunar Festival Harbinger at the Cenarion Enclave in Darnassus. You can also talk to Lunar Festival Harbingers in other capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8873] = { id = 8873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", completion = "Welcome, {name}.  Are you here to join in the festivities?", objectives = "Talk to the Lunar Festival Harbinger in the Valley of Wisdom in Orgrimmar. You can also talk to Lunar Festival Harbingers in other capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8874] = { id = 8874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", completion = "Welcome, {name}.  Are you here to join in the festivities?", objectives = "Talk to the Lunar Festival Harbinger in the entrance to the Undercity. You can also talk to Lunar Festival Harbingers in other capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8875] = { id = 8875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lunar Festival", description = "It's that time of the year, {name}!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", completion = "Welcome, {name}.  Are you here to join in the festivities?", objectives = "Talk to the Lunar Festival Harbinger at the Elder Rise in Thunder Bluff. You can also talk to Lunar Festival Harbingers in other capital cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8876] = { id = 8876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Small Rockets", progress = "I hold the secrets to creating Lunar Festival rockets, and I am happy to share my knowledge with the honored.\n\nIn exchange for coins of ancestry, I can offer you the recipe to make a small rocket...", completion = "Ah, very well.  Here are your recipes, {name}, and my Elune bless you." }
quests[8877] = { id = 8877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firework Launcher", progress = "Although rockets are a wonderful way to celebrate, in order to see their glory... they must be fired from a launcher.\n\nBring me coins of ancestry and I can offer you the knowledge to create rocket launchers like the ones you see in Moonglade.", completion = "Here you are, {name}.  Here is the schematic to create a firework launcher.  Place launchers where you wish to celebrate, and then welcome your friends to join you!" }
quests[8878] = { id = 8878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Festive Recipes", progress = "The dresses and pant suits you see are traditional clothes from many years past.  They are worn in honor of old ways and loved ones gone.\n\nIf you bring me coins of ancestry, {name}, then I will give you the pattern to create traditional red dresses or suits.", completion = "Here are the patterns, {name}.  I am sure you will find the product of this knowledge quite beautiful." }
quests[8879] = { id = 8879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Large Rockets", progress = "Large Festival rockets light up the sky brilliantly - only the cluster rockets rival their magnificence!\n\nBring me coins of ancestry, {name}, and I shall share the knowledge of their creation.", completion = "Very well - I accept these coins of ancestry.  Here are your recipes, {name}.  May you use them to spread Elune's glory!" }
quests[8880] = { id = 8880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cluster Rockets", progress = "Cluster rockets are a collection of individual rockets, and their beauty is awesome!  Bring me coins of ancestry and I will share the knowledge of their creation to you...", completion = "Here you are, {name}.  Take these recipes and learn their secrets.  I bid you fortune, and I look forward to seeing your magnificent creations." }
quests[8881] = { id = 8881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Large Cluster Rockets", progress = "Large cluster rockets require vast resources and skill to create, but their brilliance and beauty is worth that effort!  Bring me coins of ancestry and I will grant you the knowledge of their crafting.", completion = "Thank you, {name}.  Here is the recipe for large cluster rockets.  May your products bring joy and luck to all those who gaze up them." }
quests[8882] = { id = 8882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cluster Launcher", progress = "The most splendid fireworks shows must include cluster rockets, and those cluster rockets must be fired from cluster launchers!  Is it not then logical for you to learn the secrets of making cluster launchers?  Bring me coins of ancestry and I will give this knowledge to you.", completion = "Here is your schematic.  Study it closely, and learn...\n\nGood luck, {name}.  May your celebrations rival that of the Lunar Festival itself!" }
quests[8883] = { id = 8883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valadar Starsong", description = "Now that you have your Lunar Festival invitation, you may travel to Moonglade!  There you will find many revelers, and in the village of Nighthaven Valadar Starsong and his sister Fariel await those eager to participate in the celebration.\n\nTravel to Moonglade through the greater moonlight and speak with Valadar Starsong; see what prizes you might gain during the festival!", completion = "{name}, welcome to Nighthaven, host of the Lunar Festival!  Although our village is normally remote and sequestered from the peoples of Azeroth, during this time of celebration we open our arms and hearts to all.\n\nEnjoy your visit, {name}, and speak with me or my sister again when ready.", objectives = "Use your Lunar Festival Invitation in the moonlight to travel to Moonglade. Speak with Valadar Starsong in Nighthaven when you arrive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[8884] = { id = 8884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fish Heads, Fish Heads...", description = "Greetings, {class}.  Take a look toward the shore; what do you see?  That's right, our beach... our Tranquil Shore, has been infested with the malignancy known as the murloc.\n\nThis blight will not stand!\n\nI have a task for you.  If you feel that you're up to it, I would have their heads!  Let us see if we can put a dent in their numbers so large that, if they have any sense at all, they will return to the murky depths from which they sprang!", sourceObjective = "Collect 8 Grimscale Murloc Heads. Return them to Hathvelion Sungaze in the Eversong Woods on the bluff overlooking the Tranquil Shore.", progress = "We rangers of the Farstrider Retreat are dedicated to setting right the damage that has been wreaked upon our fair lands.  We will go to any length to do so.\n\nI trust that you have returned with the murloc heads I tasked you to gather?", completion = "A job well done, {class}.  By the smell of it, I'd say you returned all that I asked for, and possibly more.  I'm sure we can find some use for these, in a stew, or somesuch.\n\nAlas, it does not appear that your efforts have done the trick; the murlocs are not in retreat.  This calls for more direct action!", sourceObjectiveStatus = "unverified-source-field" }
quests[8885] = { id = 8885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Mmmrrrggglll", description = "The Grimscale murlocs have not been scared off by your efforts. But, I think I know what will send them packing, as well as get me some personal retribution.\n\nThey have a murloc chieftain that calls itself Mmmrrrggglll. It wanders the Golden Strand south of the river inlet. The beast once slew a compatriot of mine, and now wears his ring in open defiance and mockery.\n\nSlay Mmmrrrggglll, and bring back my friend's ring. Then we shall see these monsters cowed!", sourceObjective = "Retrieve the Ring of Mmmrrrggglll from the Grimscale chieftain's dead clutches. Return it to Hathvelion Sungaze in the Eversong Woods on the bluff overlooking the Tranquil Shore.", progress = "You are the instrument of my success and revenge, {class}. Have you the ring?", completion = "At last! Though the Grimscale did not route, as hoped, it was entertaining to watch them panic in confusion when you laid low their so-called chieftain. You have my thanks, and the gratitude of the sin'dorei of Silvermoon City!\n\nPlease, take one of these in thanks for the service that you have rendered.", sourceObjectiveStatus = "unverified-source-field" }
quests[8886] = { id = 8886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimscale Pirates!", description = "Thank goodness for you, {class}! Those slimy Grimscale murlocs have pirated away my cargo! It's bad enough that the Wretched have stolen what little magical goods I had, but the murlocs took the rest! What has this land come to?\n\nCould you retrieve my cargo? I can't expect that you'd be able to get all of it back, but I'll be grateful for any of it at this point. It was the Grimscale murlocs in the huts, just to the west and south of the anchorage on the Golden Strand, I'm sure of it!", sourceObjective = "Retrieve 6 of Captain Kelisendra's Cargo and return them to Captain Kelisendra at the defended camp just to the east of the Sunsail Anchorage in Eversong Woods.", progress = "I am grateful for the assistance of someone like you, {name}. It almost puts a smile on my face. But then I realize what these monsters have done to my ship and what's happening to Quel'Thalas.\n\nHave you managed to retrieve any of my cargo?", completion = "You did it! You've saved me from ruin and delivered my revenge upon those disgusting creatures!\n\nNow if I can just get these pretty rangers here to help me with this cargo, I'll finally get out of here! I'll have to come back when Velendris has retaken the shipyard.\n\nHere, take this coin. It's what little I can afford, and the least that I can do to reward your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[8887] = { id = 8887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captain Kelisendra's Lost Rutters", description = "Interesting... what you have found here is a water-proofed, leather tube containing a number of sheets of parchment. By the markings upon them, the pages are clearly navigation rutters, and each bears the signature of one Captain Kelisendra.\n\nYou've heard of a small, defended camp just east of the nearby Sunsail Anchorage. Maybe the captain is there?", sourceObjective = "Return Captain Kelisendra's Lost Rutters to Captain Kelisendra at the defended camp just to the east of the Sunsail Anchorage in Eversong Woods.", progress = "Hello, {class}, you're a sight for sore eyes. I know, it's crazy for me to be here, what with the anchorage overrun by the Wretched. Velendris and his rangers have sworn to protect me on the condition that I get out of here as soon as I've recovered my cargo.\n\nWhat's that you have there... it looks vaguely familiar?", completion = "Oh you sweet, sweet {class}! I had no idea that those disgusting Grimscale murlocs had also pirated away with my navigation rutters! Without them, I would have no chance of navigating the seas again once we retake the anchorage and repair the ship.\n\nThank you very much! Here, take this coin as a sign of my appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[8888] = { id = 8888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magister's Apprentice", description = "{class}, hear my request. For reasons that I cannot go into now, I decided to shut down my nearby school. A few days ago, I sent one of my pupils, Apprentice Loralthalis, there with this very task. I have not heard back from her since.\n\nWill you go to Duskwither Spire and check in on her, to make sure that she is well? You'll find it by heading north on the path out of Farstrider Retreat, then go to the right when the road branches.", sourceObjective = "Speak with Apprentice Loralthalis near Duskwither Spire in Eversong Woods.", completion = "The magister was concerned for my wellbeing? How sweet; I wish that he had shown such an interest before, when we were at the Spire.\n\nThat doesn't matter now. Please listen carefully, {class}, as I have a favor to ask of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[8889] = { id = 8889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage classic-master c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceFlavor = "classic-master", sourceRevision = "c51dc2e5141f070f5b92de190521d79e8dccaeab", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deactivating the Spire", description = "As you may know, Magister Duskwither sent me back here to shut down the power sources that feed the Spire. There are three of them, each located in a different place inside.\n\nUnfortunately, I appear to be too late, and Duskwither Spire has been overrun with strange, magical creatures. While I haven't the expertise to accomplish this task, surely a {class}, such as yourself, could do so easily?", sourceObjective = "Deactivate the 3 Duskwither Spire Power Sources inside Duskwither Spire. Then return the Deactivating Jewel to Apprentice Loralthalis in Eversong Woods.", progress = "I can't be certain from this distance... have you already shut down the power to Duskwither Spire?", completion = "I am grateful to you for your assistance, but saddened to hear that some of my fellow apprentices have fallen to their addiction.\n\nWith the power to the Spire cut off, I think I'll stay here a while and see if things calm down long enough for me to sneak in and retrieve their remains.", sourceObjectiveStatus = "unverified-source-field" }
